{
    "query": "Which plugin enforces authentication on a Kong service?",
    "top_k": 3
}

{
    "model": "{{meta_model}}",
    "messages": [
        {
            "role": "user",
            "content": "Reply with exactly this JSON and nothing else: {\"ok\":true}"
