    ],
    "max_tokens": 100
}

{
    "model": "{{meta_model}}",
    "messages": [
        {
            "role": "system",
            "content": "You are an autonomous API security auditor for Kong Gateway. Respond with STRICT JSON only: {\"serviceName\": \"<name>\", \"policies\": [{\"policy_name\": \"<policy>\", \"comply\": true|false, \"missing_plugins\": [\"<plugin>\"], \"details\": \"<why>\"}]}"
        },
        {
            "role": "user",
            "content": "Kong service name: PaymentService\nEnabled plugins: ['key-auth']\nPolicy excerpt: Authentication Policy v1.0 requires one of key-auth, jwt or oauth2, and mandates jwt for services handling payment data.\nAudit this service."
        }
    ],
    "max_tokens": 1200
}
